def _repair_ubuntu_gui_shortcuts(applications_dir=None):
    """Repair old Ubuntu launchers so opening the GUI never opens a terminal."""
    if platform.system() != "Linux":
        return False
    applications_dir = applications_dir or os.path.expanduser(
        "~/.local/share/applications")
    changed = False
    for filename in (
            "mindspark-bot-ubuntu.desktop",
            "mindspark-bot-ubuntu-managed.desktop",
            "mindspark-bot-ubuntu-updater.desktop"):
        path = os.path.join(applications_dir, filename)
        try:
            with open(path, "r", encoding="utf-8") as handle:
                original = handle.read()
            updated = re.sub(
                r"(?mi)^Terminal[ \t]*=[ \t]*true[ \t]*$", "Terminal=false", original)
            if updated == original:
                continue
            mode = os.stat(path).st_mode
            temporary = f"{path}.mindspark-{os.getpid()}.tmp"
            try:
                with open(temporary, "w", encoding="utf-8", newline="\n") as handle:
                    handle.write(updated)
                    handle.flush()
                    os.fsync(handle.fileno())
                os.chmod(temporary, mode)
                os.replace(temporary, path)
            finally:
                if os.path.exists(temporary):
                    os.unlink(temporary)
            changed = True
        except FileNotFoundError:
            continue
        except Exception as error:
            try:
                log_dir = os.path.expanduser("~/.local/state/mindspark-bot")
                os.makedirs(log_dir, exist_ok=True)
                with open(os.path.join(log_dir, "launcher-repair.log"),
                          "a", encoding="utf-8") as handle:
                    handle.write(f"Could not repair {path}: {error}\n")
            except Exception:
                pass
    if changed:
        database_tool = shutil.which("update-desktop-database")
        if database_tool:
            try:
                subprocess.run(
                    [database_tool, applications_dir], check=False,
                    stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
            except Exception:
                pass
    return changed


def _restart_after_ubuntu_launcher_repair():
    """Detach once so a terminal opened by an old shortcut can close immediately."""
    if not _repair_ubuntu_gui_shortcuts():
        return False
    log_dir = os.path.expanduser("~/.local/state/mindspark-bot")
    os.makedirs(log_dir, exist_ok=True)
    log_path = os.path.join(log_dir, "launcher-repair.log")
    with open(log_path, "a", encoding="utf-8") as log_file:
        subprocess.Popen(
            [sys.executable, os.path.abspath(__file__)],
            cwd=os.path.expanduser("~"),
            stdin=subprocess.DEVNULL,
            stdout=log_file,
            stderr=subprocess.STDOUT,
            start_new_session=True,
            close_fds=True,
        )
    return True


def _ensure_ubuntu_unicode_fonts():
    """Best-effort Linux browser font fallback for Mindspark Hindi/Unicode text."""
    if platform.system() != "Linux":
        return

    font_dir = os.path.expanduser("~/.local/share/fonts/mindspark-bot")
    log_dir = os.path.expanduser("~/.local/state/mindspark-bot")
    log_path = os.path.join(log_dir, "browser-font-setup.log")
    os.makedirs(font_dir, exist_ok=True)
    os.makedirs(log_dir, exist_ok=True)

    fonts = {
        "NotoSans-Variable.ttf": (
            "https://raw.githubusercontent.com/google/fonts/main/ofl/notosans/"
            "NotoSans%5Bwdth%2Cwght%5D.ttf"
        ),
        "NotoSansDevanagari-Variable.ttf": (
            "https://raw.githubusercontent.com/google/fonts/main/ofl/notosansdevanagari/"
            "NotoSansDevanagari%5Bwdth%2Cwght%5D.ttf"
        ),
        "NotoSansSymbols2-Regular.ttf": (
            "https://raw.githubusercontent.com/google/fonts/main/ofl/notosanssymbols2/"
            "NotoSansSymbols2-Regular.ttf"
        ),
    }

    def write_log(message):
        try:
            with open(log_path, "a", encoding="utf-8") as handle:
                handle.write(time.strftime("%Y-%m-%d %H:%M:%S ") + str(message) + "\\n")
        except Exception:
            pass

    for filename, url in fonts.items():
        destination = os.path.join(font_dir, filename)
        try:
            if os.path.isfile(destination) and os.path.getsize(destination) > 100_000:
                continue
            temp_path = destination + ".download"
            request = urllib.request.Request(
                url, headers={"User-Agent": f"MindsparkBot/{APP_VERSION}"})
            with urllib.request.urlopen(request, timeout=20) as response, open(temp_path, "wb") as out_file:
                shutil.copyfileobj(response, out_file)
            if os.path.getsize(temp_path) <= 100_000:
                raise RuntimeError("downloaded font file was unexpectedly small")
            os.replace(temp_path, destination)
            write_log(f"Installed browser fallback font: {filename}")
        except Exception as error:
            try:
                if os.path.exists(destination + ".download"):
                    os.remove(destination + ".download")
            except Exception:
                pass
            write_log(f"Could not install {filename}: {error}")

    fc_cache = shutil.which("fc-cache")
    if fc_cache:
        try:
            subprocess.run(
                [fc_cache, "-f", font_dir],
                stdout=subprocess.DEVNULL,
                stderr=subprocess.DEVNULL,
                timeout=30,
                check=False,
            )
        except Exception as error:
            write_log(f"Fontconfig refresh failed: {error}")



def _matches_step0_initial_url(current_url, initial_url=LOGIN_URL):
    """Conservative Step 0 URL comparison for the FIRST Security Check only.

    Normalizes only a harmless trailing slash difference. Deliberately does
    NOT compare by domain alone - a tab that navigated anywhere past the
    initial Step 0 page must never match here.
    """
    def normalize(u):
        u = (u or "").strip().split("#", 1)[0].split("?", 1)[0]
        return u.rstrip("/")

    return normalize(current_url) == normalize(initial_url)





